package com.evidencevault.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="evidence_verifications")
public class EvidenceVerification { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER,optional=false) @JoinColumn(name="evidence_id") private Evidence evidence; @ManyToOne(fetch=FetchType.EAGER,optional=false) @JoinColumn(name="verified_by") private User verifiedBy; @Column(nullable=false,length=64) private String expectedHash; @Column(nullable=false,length=64) private String calculatedHash; @Column(nullable=false,length=30) private String result; private LocalDateTime verifiedAt;
 @PrePersist void pre(){verifiedAt=LocalDateTime.now();} public Long getId(){return id;} public Evidence getEvidence(){return evidence;} public void setEvidence(Evidence v){evidence=v;} public User getVerifiedBy(){return verifiedBy;} public void setVerifiedBy(User v){verifiedBy=v;} public String getExpectedHash(){return expectedHash;} public void setExpectedHash(String v){expectedHash=v;} public String getCalculatedHash(){return calculatedHash;} public void setCalculatedHash(String v){calculatedHash=v;} public String getResult(){return result;} public void setResult(String v){result=v;} public LocalDateTime getVerifiedAt(){return verifiedAt;} }
